mkdir -p src test && cat > package.json <<'EOF'
{
  "name": "resolve-realpath",
  "version": "1.0.0",
  "description": "Resolve symlinks in a file path to its canonical filesystem path",
  "type": "module",
  "main": "src/realpath.js",
  "bin": {
    "resolve-realpath": "src/cli.js"
  },
  "scripts": {
    "start": "node src/cli.js",
    "test": "node --test test/"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}
EOF
cat > src/realpath.js <<'EOF'
import fs from 'node:fs';
import path from 'node:path';

// Both variants use libuv's uv_fs_realpath (the OS realpath(3) /
// GetFinalPathNameByHandle). The default fs.realpathSync is a JS
// reimplementation whose results differ across platforms and Node versions
// (drive-letter casing, subst/network drives, long paths), so we avoid it.

/**
 * Resolve `p` to its canonical absolute path, following all symlinks.
 * Relative paths are resolved against `cwd`. Rejects if the path does not exist.
 */
export async function resolveRealPath(p, { cwd = process.cwd() } = {}) {
  return fs.promises.realpath(path.resolve(cwd, p));
}

/** Synchronous counterpart of resolveRealPath. */
export function resolveRealPathSync(p, { cwd = process.cwd() } = {}) {
  return fs.realpathSync.native(path.resolve(cwd, p));
}
EOF
cat > src/cli.js <<'EOF'
#!/usr/bin/env node
import { resolveRealPath } from './realpath.js';

const args = process.argv.slice(2);
if (args.length === 0) {
  console.error('Usage: resolve-realpath <path> [path...]');
  process.exit(2);
}

let failed = false;
for (const arg of args) {
  try {
    console.log(await resolveRealPath(arg));
  } catch (err) {
    failed = true;
    console.error(`resolve-realpath: ${arg}: ${err.code ?? err.message}`);
  }
}
process.exit(failed ? 1 : 0);
EOF
chmod +x src/cli.js
cat > test/realpath.test.js <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { resolveRealPath, resolveRealPathSync } from '../src/realpath.js';

let root;
before(() => {
  // tmpdir itself may be a symlink (e.g. /tmp -> /private/tmp on macOS).
  root = fs.realpathSync.native(fs.mkdtempSync(path.join(os.tmpdir(), 'rp-')));
  fs.mkdirSync(path.join(root, 'real/sub'), { recursive: true });
  fs.writeFileSync(path.join(root, 'real/sub/file.txt'), 'x');
  fs.symlinkSync(path.join(root, 'real'), path.join(root, 'link-abs'), 'dir');
  fs.symlinkSync('real/sub', path.join(root, 'link-rel'), 'dir');
  fs.symlinkSync('link-rel/file.txt', path.join(root, 'chain'));
  fs.symlinkSync('loop-b', path.join(root, 'loop-a'));
  fs.symlinkSync('loop-a', path.join(root, 'loop-b'));
});
after(() => fs.rmSync(root, { recursive: true, force: true }));

const expected = () => path.join(root, 'real/sub/file.txt');

for (const [name, fn] of [['async', resolveRealPath], ['sync', resolveRealPathSync]]) {
  test(`${name}: resolves absolute directory symlink`, async () => {
    assert.equal(await fn(path.join(root, 'link-abs/sub/file.txt')), expected());
  });

  test(`${name}: resolves relative symlink chain`, async () => {
    assert.equal(await fn(path.join(root, 'chain')), expected());
  });

  test(`${name}: resolves relative input against cwd and normalizes ..`, async () => {
    assert.equal(await fn('link-abs/sub/../sub/file.txt', { cwd: root }), expected());
  });

  test(`${name}: throws ENOENT for missing path`, async () => {
    await assert.rejects(async () => fn(path.join(root, 'nope')), { code: 'ENOENT' });
  });

  test(`${name}: throws ELOOP for symlink cycle`, async () => {
    await assert.rejects(async () => fn(path.join(root, 'loop-a')), { code: 'ELOOP' });
  });
}
EOF
cat > .gitignore <<'EOF'
node_modules/
EOF
npm test 2>&1 | tail -15; ln -sfn /work/src /tmp/srclink && node src/cli.js /tmp/srclink/cli.js /nope; echo "exit=$?"

